SELECT 
  FROM tb_member_oauth o
 WHERE o.provider         = #{provider}
   AND o.provider_user_id = #{providerUserId}
   AND o.delete_yn        = 'N'
 LIMIT 1

SELECT 
  FROM tb_member_oauth o
 WHERE o.provider         = #{provider}
   AND o.provider_user_id = #{providerUserId}
 ORDER BY o.created_at DESC
 LIMIT 1

SELECT COUNT(*)
  FROM tb_member_oauth o
 WHERE o.member_id  = #{memberId}
   AND o.provider   = #{provider}
   AND o.delete_yn  = 'N'

